UPDATE series SET title = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(title, '&#038;', '&'), '&amp;', '&'), '&#8217;', '’'), '&#8216;', '‘'), '&#8220;', '“'), '&#8221;', '”'), '&#039;', ''''), '&#39;', ''''), '&quot;', '"'), '&ldquo;', '“'), '&rdquo;', '”'), '&lsquo;', '‘'), '&rsquo;', '’'), '&hellip;', '…'), '&mdash;', '—'), '&ndash;', '–'), '&nbsp;', ' ') WHERE title LIKE '%&%' OR title LIKE '%&#%';

UPDATE series SET synopsis = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(synopsis, '&#038;', '&'), '&amp;', '&'), '&#8217;', '’'), '&#8216;', '‘'), '&#8220;', '“'), '&#8221;', '”'), '&#039;', ''''), '&#39;', ''''), '&quot;', '"'), '&ldquo;', '“'), '&rdquo;', '”'), '&lsquo;', '‘'), '&rsquo;', '’'), '&hellip;', '…'), '&mdash;', '—'), '&ndash;', '–'), '&nbsp;', ' ') WHERE synopsis LIKE '%&%' OR synopsis LIKE '%&#%';

UPDATE series SET alt_titles = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(alt_titles, '&#038;', '&'), '&amp;', '&'), '&#8217;', '’'), '&#8216;', '‘'), '&#8220;', '“'), '&#8221;', '”'), '&#039;', ''''), '&#39;', ''''), '&quot;', '"'), '&ldquo;', '“'), '&rdquo;', '”'), '&lsquo;', '‘'), '&rsquo;', '’'), '&hellip;', '…'), '&mdash;', '—'), '&ndash;', '–'), '&nbsp;', ' ') WHERE alt_titles LIKE '%&%' OR alt_titles LIKE '%&#%';